// Define XPath for element extraction
const path = '//div[@class="newbox"]/ul/li';

u = java.get('url');
// Attempt to fetch elements using initial response
let c = java.getElement(path);  // First attempt to get elements

// Always clear cookies before initiating verification
cookie.removeCookie(source.getKey());

// Check for "搜索关键词" to decide bypass behavior
if (result.includes("搜索结果")) {
  // Directly use the XPath extraction without browser verification
  c = java.getElement(path);  // Skip browser verification
} else {
  // Display a toast message to indicate bypass attempt
  java.longToast("过盾");  // Display toast message

  // Use startBrowserAwait to perform browser-based verification
  const response = java.startBrowserAwait(u, "验证").body();

  // Set the content from the new response to allow further processing
  java.setContent(response);

